/// <summary>
/// Contract class for Claim Sales Order Invoiced Event
/// </summary>
[DataContract]
public final class METClaimSOInvoicedBusinessEventContract  extends BusinessEventsContract
{
    private SalesReturnItemNum rmaNumber;
    SalesId salesId;
    ReturnReasonCodeId returnReasonCodeId;
    METSalesOrderTypeID metSalesOrderTypeID;

}

Method.Source:
/// <summary>
/// Parm method for RMA number 
/// </summary>
/// <param name = "_rmaNumber">RMA number</param>
/// <returns>RMA Number</returns>
[DataMember(identifierStr(SalesReturnItemNum)), BusinessEventsDataMember("@SYS24699")]
public SalesReturnItemNum parmRMANumber(SalesReturnItemNum _rmaNumber = rmaNumber)
{
    rmaNumber = _rmaNumber;

    return rmaNumber;
}

/// <summary>
/// Parm method for Sales order number
/// </summary>
/// <param name = "_salesId">Sales order number</param>
/// <returns>Sales order number</returns>
[DataMember(identifierStr(SalesId)), BusinessEventsDataMember("@SYS19627")]
public SalesId parmSalesId(SalesId _salesId = salesId)
{
    salesId = _salesId;

    return salesId;
}

/// <summary>
/// Parm method for reason code
/// </summary>
/// <param name = "_returnReasonCodeId">Reason code</param>
/// <returns>Reason code</returns>
[DataMember(identifierStr(ReturnReasonCodeId)), BusinessEventsDataMember("@SYS106030")]
public ReturnReasonCodeId parmReturnReasonCode(ReturnReasonCodeId _returnReasonCodeId = returnReasonCodeId)
{
    returnReasonCodeId = _returnReasonCodeId;

    return returnReasonCodeId;
}

/// <summary>
/// Parm method for MET sales order type
/// </summary>
/// <param name = "_metSalesOrderTypeID">MET sales order type</param>
/// <returns>MET sales order type</returns>
[DataMember(identifierStr(METSalesOrderTypeID)), BusinessEventsDataMember("@MET:METMetcashSalesOrder")]
public METSalesOrderTypeID parmMETSalesOrderType(METSalesOrderTypeID _metSalesOrderTypeID = metSalesOrderTypeID)
{
    metSalesOrderTypeID = _metSalesOrderTypeID;

    return metSalesOrderTypeID;
}

/// <summary>
/// Create contract instance using SalesTable
/// </summary>
/// <param name = "_salesTable">Salestable</param>
/// <returns>An instance of <c>METClaimSOInvoicedBusinessEventContract</c></returns>
public static METClaimSOInvoicedBusinessEventContract newFromSalesTable(SalesTable _salesTable)
{
    var contract = new METClaimSOInvoicedBusinessEventContract();
    contract.initialize(_salesTable);

    return contract;
}

/// <summary>
/// Initialize the data contract
/// </summary>
/// <param name = "_salesTable">SalesTable</param>
private void initialize(SalesTable _salesTable)
{
    rmaNumber = _salesTable.ReturnItemNum;
    salesId = _salesTable.SalesId;
    returnReasonCodeId = _salesTable.ReturnReasonCodeId;
    metSalesOrderTypeID = _salesTable.METSalesOrderType;

}
